"""Unit tests for risk.annualize (spine: daily values pass through)."""

from __future__ import annotations

import dataclasses
from collections.abc import Callable
from typing import Any

import pytest

from risk.annualize import annualize
from risk.types import Returns, VolSeries


def vol_from_sample(data: dict[str, Any], *, annualized: bool) -> VolSeries:
    r = data["returns"]
    returns = Returns(
        base_date=r["base_date"],
        dates=tuple(r["dates"]),
        tickers=tuple(r["tickers"]),
        values={t: tuple(v) for t, v in r["values"].items()},
    )
    return VolSeries(
        returns=returns,
        window=data["window"],
        annualized=annualized,
        values={t: tuple(v) for t, v in data["values"].items()},
    )


def test_daily_sample_becomes_annualized_with_values_passed_through(
    contract_sample: Callable[[str], dict[str, Any]],
) -> None:
    daily = vol_from_sample(contract_sample("risk.VolSeries"), annualized=False)

    out = annualize(daily)

    assert out.annualized is True
    assert out.returns == daily.returns
    assert out.window == 2
    assert out.values["ACME"][:2] == (None, None)
    assert out.values["ACME"][2] == pytest.approx(0.5573826203591309)
    assert out.values["BOLT"][4] == pytest.approx(0.16124865888434922)
    assert dataclasses.replace(out, annualized=False) == daily


def test_already_annualized_raises(contract_sample: Callable[[str], dict[str, Any]]) -> None:
    annual = vol_from_sample(contract_sample("risk.VolSeries"), annualized=True)

    with pytest.raises(ValueError, match="already annualized"):
        annualize(annual)
"""Intent tests for risk.annualize (M1-T18, RISK-03, TC-06)."""

from __future__ import annotations

from collections.abc import Callable

import pytest

from risk import annualize
from risk.types import Returns, VolSeries


def _returns(data: dict) -> Returns:
    return Returns(
        base_date=data["base_date"],
        dates=tuple(data["dates"]),
        tickers=tuple(data["tickers"]),
        values={t: tuple(float(v) for v in vs) for t, vs in data["values"].items()},
    )


def _vol(data: dict) -> VolSeries:
    return VolSeries(
        returns=_returns(data["returns"]),
        window=data["window"],
        annualized=data["annualized"],
        values={
            t: tuple(None if v is None else float(v) for v in vs)
            for t, vs in data["values"].items()
        },
    )


@pytest.mark.intent
def test_tc06_scales_each_daily_value_and_keeps_gaps(
    golden: Callable[[str, str], tuple[dict, dict]],
) -> None:
    given, expected = golden("risk", "TC-06")
    vol = _vol(given["vol"])
    tol = expected["tol"]

    result = annualize(vol)

    assert result.annualized is expected["annualized"]
    assert result.returns == vol.returns
    assert result.window == vol.window
    assert set(result.values) == set(expected["values"])
    for ticker, want in expected["values"].items():
        got = result.values[ticker]
        assert len(got) == len(want)
        for g, w in zip(got, want, strict=True):
            if w is None:
                assert g is None
            else:
                assert g is not None
                assert g == pytest.approx(w, abs=tol)


@pytest.mark.intent
def test_tc06_default_is_252_trading_days(
    golden: Callable[[str, str], tuple[dict, dict]],
) -> None:
    given, expected = golden("risk", "TC-06")
    vol = _vol(given["vol"])
    tol = expected["tol"]

    explicit = annualize(vol, periods_per_year=252)

    for ticker, want in expected["values"].items():
        for g, w in zip(explicit.values[ticker], want, strict=True):
            if w is None:
                assert g is None
            else:
                assert g == pytest.approx(w, abs=tol)


@pytest.mark.intent
def test_annualizing_an_annualized_series_is_a_value_error(
    contract_sample: Callable[[str], dict],
) -> None:
    vol = _vol(contract_sample("risk.VolSeries"))
    assert vol.annualized is True

    with pytest.raises(ValueError, match=r"(?i)annualiz"):
        annualize(vol)


@pytest.mark.intent
def test_annualizing_the_result_again_is_a_value_error(
    golden: Callable[[str, str], tuple[dict, dict]],
) -> None:
    given, _ = golden("risk", "TC-06")
    once = annualize(_vol(given["vol"]))

    with pytest.raises(ValueError, match=r"(?i)annualiz"):
        annualize(once)
