from collections.abc import Mapping
from dataclasses import dataclass


@dataclass(frozen=True)
class Returns:
    """Daily log returns, dated after `base_date`, the prices' first date."""

    base_date: str
    dates: tuple[str, ...]
    tickers: tuple[str, ...]
    values: Mapping[str, tuple[float, ...]]


@dataclass(frozen=True)
class VolSeries:
    """Rolling volatility aligned to `returns.dates`; None until `window` earlier returns exist."""

    returns: Returns
    window: int
    annualized: bool
    values: Mapping[str, tuple[float | None, ...]]


@dataclass(frozen=True)
class TickerSummary:
    """Whole-period statistics for one ticker."""

    ticker: str
    ann_return: float
    ann_vol: float
    sharpe: float
    last_vol: float | None


@dataclass(frozen=True)
class Drawdown:
    """The deepest fall below the running peak (`depth` <= 0) with its peak and trough dates."""

    ticker: str
    depth: float
    peak_date: str
    trough_date: str


@dataclass(frozen=True)
class Report:
    """The written report: one row per ticker, sorted, the same rows as the file at `path`."""

    path: str
    rows: tuple[Mapping[str, object], ...]
